const cards = [
{id:'validation',title:'Backend Validation',zh:'后端校验 · Trust the rules, not the request.',tag:'API DESIGN',definition:'Validate incoming data on the server to protect data integrity and enforce business rules.',translation:'前端校验帮助用户正确填写；后端校验确保绕过页面的请求也必须遵守规则。类型正确，不代表业务有效。',example:'// quantity is already an integer. Is it valid?\nif (quantity <= 0)\n{\n    return Results.BadRequest("Quantity must be positive.");\n}',takeaway:'Type validation: Can it be parsed as an integer?\nBusiness validation: Is that integer allowed?',answer:'We need backend validation because clients can call the API directly and bypass frontend validation. The backend must validate incoming data to protect data integrity and enforce business rules.',question:'The frontend prevents negative quantities. Why must the API still reject quantity = -2?',solution:'A caller can bypass the UI. Subtracting -2 would increase stock by 2 and create an invalid order. Validate quantity > 0 before modifying data.'},
{id:'race',title:'Race Conditions',zh:'竞态条件 · When timing changes the outcome.',tag:'CONCURRENCY',definition:'A race condition occurs when the outcome depends on the timing of concurrent operations.',translation:'“先查询是否可用，再创建预订”是两个步骤。两个请求可能都在对方保存之前读到“可用”，从而重复预订。',example:'Request A → checks availability → Available\nRequest B → checks availability → Available\nRequest A → creates booking     → Success\nRequest B → creates booking     → Success\n\nResult: two overlapping bookings for one vehicle.',takeaway:'The availability check and booking creation are not atomic. A transaction alone does not automatically prevent this; the isolation and concurrency strategy matter.',answer:'Both requests may succeed because each request can check availability before the other saves its booking. This race condition can lead to double booking. We need database-enforced concurrency control.',question:'Does wrapping the availability check and INSERT in a transaction always prevent double booking? Explain.',solution:'No. For example, under read committed isolation, both transactions may observe no booking before either inserts. Use an appropriate strategy such as locking a shared vehicle row within the transaction, a supported database exclusion constraint, or serializable isolation with retry handling.'},
{id:'idempotency',title:'Idempotency',zh:'幂等性 · Retry safely, without duplicate effects.',tag:'API RELIABILITY',definition:'Repeating the same operation has the same intended effect as performing it once.',translation:'第一次请求可能已成功，但响应丢失。同一次预订的重试使用相同的幂等键，让服务端识别它，而不是再创建一笔。',example:'POST /api/bookings\nIdempotency-Key: booking-attempt-7f92\n\nFirst request → create booking → save key + result\nSame-key retry → return the existing result\nNew booking intention → use a new key',takeaway:'Debouncing reduces repeated triggers. Idempotency prevents duplicate business effects. Different users with different keys still need concurrency control.',answer:'The client should reuse the same idempotency key when retrying the same booking request. The backend records the key and result, so a retry does not create another booking. A unique constraint helps coordinate concurrent requests with the same key.',question:'Two different users use different keys to book the same vehicle for overlapping dates. Does idempotency prevent double booking?',solution:'No. These are distinct operations. Idempotency protects retries of one operation. Availability requires separate concurrency control. Scope keys to the user or tenant, check payload consistency, and define how in-progress requests and key expiration are handled.'},
{id:'overlap',title:'Interval Overlap',zh:'区间重叠 · Availability lives on a timeline.',tag:'DATABASE LOGIC',definition:'Two half-open time intervals overlap when each interval starts before the other interval ends.',translation:'使用 [start, end)：包含开始时间，不包含结束时间。因此一位用户 10:00 还车，另一位可以 10:00 取车。实际业务可另外加入清洁缓冲时间。',example:'// Assume valid intervals: Start < End\nbool overlaps =\n    existing.Start < requested.End &&\n    requested.Start < existing.End;\n\nExisting: Nov 10, 10:00 → Nov 12, 10:00\nRequest:  Nov 12, 10:00 → Nov 14, 10:00\nResult:   no overlap',takeaway:'Define boundary semantics, valid date ranges, time zones, and which booking statuses block availability. An overlap query detects conflicts; it does not alone prevent concurrent inserts.',answer:'I use half-open intervals, where the start is included and the end is excluded. Two bookings overlap if each starts before the other ends. This allows back-to-back bookings, assuming no turnaround buffer is required.',question:'Existing: Nov 10 at 10:00 to Nov 12 at 10:00. Do Nov 11–13 and Nov 9–10 (all at 10:00) overlap?',solution:'Nov 11–13 overlaps. Nov 9–10 does not: it ends exactly when the existing booking begins. Validate Start < End, and use consistent instants when comparing timestamps.'}
];
let state={current:'validation',statuses:{},notes:{},practice:false};let canSave=true;try{const saved=JSON.parse(localStorage.getItem('devnotes-v1')||'null');if(saved&&typeof saved==='object')state={...state,...saved,statuses:saved.statuses||{},notes:saved.notes||{}}}catch{}
let query='',revealed=false;const $=s=>document.querySelector(s);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const list=()=>cards.filter(c=>(c.title+' '+c.zh+' '+c.tag+' '+c.definition).toLowerCase().includes(query));
function save(){try{localStorage.setItem('devnotes-v1',JSON.stringify(state))}catch{canSave=false;$('#saveStatus').textContent='Progress unavailable · browser storage blocked'}}
function go(id){state.current=id;revealed=false;save();render();$('#card').scrollTop=0}
function move(delta){const a=list(),i=a.findIndex(c=>c.id===state.current);if(a[i+delta])go(a[i+delta].id)}
function render(){const a=list();let c=a.find(c=>c.id===state.current);if(!c)c=a[0];if(c)state.current=c.id;const i=a.indexOf(c);$('#topics').innerHTML=a.length?a.map((x,n)=>`<button data-id="${x.id}" class="${x===c?'active':''}" ${x===c?'aria-current="page"':''}><span class="num">0${cards.indexOf(x)+1}</span>${x.title}<small>${state.statuses[x.id]==='Confident'?'✓':'↗'}</small></button>`).join(''):'<p class="empty">No matching concepts.</p>';$('#count').textContent=String(a.length).padStart(2,'0');$('#position').textContent=c?`${String(i+1).padStart(2,'0')} / ${String(a.length).padStart(2,'0')} CONCEPTS`:'0 CONCEPTS';const done=cards.filter(x=>state.statuses[x.id]==='Confident').length;$('#percent').textContent=`${done*25}%`;$('#progress').style.width=`${done*25}%`;$('#mastered').textContent=`${done} of 4 concepts marked confident`;$('#mode').classList.toggle('selected',state.practice);$('#mode').textContent=state.practice?'◎ Practice mode · ON':'◎ Practice mode';$('#mode').setAttribute('aria-pressed',state.practice);$('#prev').disabled=!c||i<=0;$('#next').disabled=!c||i>=a.length-1;if(!c){$('#card').innerHTML='<h2>No concepts found</h2><p>Try “API”, “race”, or “数据库”.</p>';return}
const learning=`<p class="definition">${c.definition}</p><p class="zh">${c.translation}</p><div class="label">IN THE CODE / IN THE REAL WORLD</div><pre>${escapeHTML(c.example)}</pre><div class="callout">${escapeHTML(c.takeaway).replace(/\n/g,'<br>')}</div><div class="rule"></div><div class="label">SAY IT IN YOUR INTERVIEW</div><div class="answer">“${c.answer}”</div>`;
$('#card').innerHTML=`<div class="card-top"><span class="tag">${c.tag}</span><span class="read-time">◷ 3 MIN READ</span></div><h2 class="title">${c.title}</h2><p class="subtitle">${c.zh}</p>${state.practice?'':learning}<section class="practice"><div class="label">YOUR TURN · ACTIVE RECALL</div><p>${c.question}</p><textarea id="note" aria-label="Your practice answer" placeholder="Explain it in your own words… English or 中文都可以。">${escapeHTML(state.notes[c.id]||'')}</textarea><button id="reveal" class="secondary" aria-expanded="${revealed}">${revealed?'Hide':'Reveal'} suggested answer ↓</button>${revealed?`<p class="answer">${c.solution}</p>${state.practice?learning:''}`:''}</section><div class="label">HOW WELL DO YOU KNOW THIS?</div><div class="statuses">${['Learning','Needs Review','Confident'].map((s,n)=>`<button data-status="${s}" aria-pressed="${(state.statuses[c.id]||'Learning')===s}" class="${(state.statuses[c.id]||'Learning')===s?'selected':''}">${['◔','↻','✓'][n]} ${s}</button>`).join('')}</div>`;
$('#note').addEventListener('input',e=>{state.notes[c.id]=e.target.value;save()});$('#reveal').onclick=()=>{const top=$('#card').scrollTop;revealed=!revealed;render();$('#card').scrollTop=top};document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{const top=$('#card').scrollTop;state.statuses[c.id]=b.dataset.status;save();render();$('#card').scrollTop=top});document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>go(b.dataset.id));}
$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1);$('#mode').onclick=()=>{state.practice=!state.practice;revealed=false;save();render();$('#card').scrollTop=0};$('#search').oninput=e=>{query=e.target.value.toLowerCase().trim();revealed=false;render();save();$('#card').scrollTop=0};document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});
let lastWheel=0,edgeDirection=0,edgeSince=0,wheelSum=0;$('#card').addEventListener('wheel',e=>{if(e.ctrlKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)||e.target.closest('textarea'))return;const el=$('#card'),now=Date.now(),dir=Math.sign(e.deltaY);if(!dir)return;const edge=dir>0?el.scrollTop+el.clientHeight>=el.scrollHeight-3:el.scrollTop<=2;if(!edge){edgeDirection=0;wheelSum=0;return}e.preventDefault();if(now-lastWheel<850)return;if(edgeDirection!==dir||now-edgeSince>450){edgeDirection=dir;edgeSince=now;wheelSum=0}wheelSum+=Math.abs(e.deltaY)*(e.deltaMode===1?16:e.deltaMode===2?el.clientHeight:1);if(now-edgeSince<160||wheelSum<70)return;move(dir);lastWheel=now;edgeDirection=0;wheelSum=0},{passive:false});render();save();
